{"cmd":"cat > /root/output/js/visualization.js <<'JS'
/* Deterministic D3 visualization for stock bubbles + table.
   - Fixed sizes and force ticks.
   - Sorted input for stable layout.
*/

const width = 720;
const height = 560;
const center = { x: width / 2, y: height / 2 };
const clusterRadius = 120;
const ETF_RADIUS = 14;
const tooltip = d3.select('#tooltip');
const parseDate = d3.timeParse('%Y-%m-%d');

const priceHistoryCache = new Map();
let activeTooltipTicker = null;
let selectedTicker = null;

const svg = d3.select('#bubble-chart')
  .append('svg')
  .attr('viewBox', `0 0 ${width} ${height}`)
  .attr('width', '100%')
  .attr('height', height)
  .attr('role', 'img')
  .attr('aria-label', 'Bubble chart of stocks by sector and market capitalization.');

const nodeLayer = svg.append('g').attr('class', 'nodes');

function formatMarketCap(value) {
  if (value == null || Number.isNaN(value)) return 'N/A';
  const abs = Math.abs(value);
  if (abs >= 1e12) return `${d3.format('.2f')(value / 1e12)}T`;
  if (abs >= 1e9) return `${d3.format('.2f')(value / 1e9)}B`;
  if (abs >= 1e6) return `${d3.format('.2f')(value / 1e6)}M`;
  if (abs >= 1e3) return `${d3.format('.2f')(value / 1e3)}K`;
  return d3.format(',')(value);
}

function positionTooltip(event) {
  tooltip
    .style('left', `${event.pageX + 14}px`)
    .style('top', `${event.pageY - 12}px`);
}

function hideTooltip() {
  activeTooltipTicker = null;
  tooltip.classed('visible', false);
  tooltip.selectAll('*').remove();
}

function tooltipHtml(d) {
  return `
    <div class="tip-title">${d.ticker}</div>
    <div class="tip-subtitle">${d.fullName}</div>
    <div class="tip-sector">Sector: ${d.sector}</div>
    <div class="tip-sparkline">
      <div class="tip-sparkline-label">Recent close (60d)</div>
      <svg width="180" height="60" aria-hidden="true"></svg>
    </div>
  `;
}

function renderSparkline(svgSel, series) {
  svgSel.selectAll('*').remove();
  if (!series || series.length < 2) return;
  const w = +svgSel.attr('width');
  const h = +svgSel.attr('height');
  const x = d3.scaleTime()
    .domain(d3.extent(series, d => d.date))
    .range([0, w]);
  const y = d3.scaleLinear()
    .domain(d3.extent(series, d => d.close))
    .nice()
    .range([h - 4, 4]);

  const line = d3.line()
    .x(d => x(d.date))
    .y(d => y(d.close));

  svgSel.append('path')
    .datum(series)
    .attr('class', 'sparkline')
    .attr('d', line);

  svgSel.append('circle')
    .attr('class', 'sparkline-dot')
    .attr('r', 2.8)
    .attr('cx', x(series[series.length - 1].date))
    .attr('cy', y(series[series.length - 1].close));
}

function loadPriceHistory(ticker) {
  if (priceHistoryCache.has(ticker)) return priceHistoryCache.get(ticker);
  const primary = `data/indiv-stock/${ticker}.csv`;
  const fallback = `data/indiv-stock/${ticker.toLowerCase()}.csv`;
  const promise = d3.csv(primary, d => ({
    date: parseDate(d.Date),
    close: +d.Close
  })).catch(() => d3.csv(fallback, d => ({
    date: parseDate(d.Date),
    close: +d.Close
  })).catch(() => null));

  priceHistoryCache.set(ticker, promise);
  return promise;
}

function setSelected(ticker, nodeSelection, rowSelection) {
  selectedTicker = ticker;
  nodeSelection.classed('selected', d => d.ticker === ticker);
  rowSelection.classed('selected', d => d.ticker === ticker);
}

function buildLegend(sectors, color) {
  const legend = d3.select('#legend')
    .append('div')
    .attr('class', 'legend');

  const items = legend.selectAll('div')
    .data(sectors)
    .enter()
    .append('div')
    .attr('class', 'legend-item');

  items.append('span')
    .attr('class', 'legend-swatch')
    .style('background-color', d => color(d));

  items.append('span')
    .attr('class', 'legend-label')
    .text(d => d);
}

d3.csv('data/stock-descriptions.csv', d => ({
  ticker: d.ticker,
  sector: d.sector,
  fullName: d['full name'],
  marketCap: d.marketCap === '' ? null : +d.marketCap,
  isEtf: d.sector === 'ETF' || d.marketCap === ''
})).then(data => {
  const sectors = Array.from(new Set(data.map(d => d.sector))).sort(d3.ascending);
  const color = d3.scaleOrdinal()
    .domain(sectors)
    .range(d3.schemeTableau10);

  const marketCaps = data.filter(d => !d.isEtf && d.marketCap != null).map(d => d.marketCap);
  const rScale = d3.scaleSqrt()
    .domain([d3.min(marketCaps), d3.max(marketCaps)])
    .range([12, 44]);

  const nodes = data
    .map(d => ({
      ...d,
      radius: d.isEtf ? ETF_RADIUS : rScale(d.marketCap)
    }))
    .sort((a, b) => d3.ascending(a.sector, b.sector) || d3.ascending(a.ticker, b.ticker));

  const sectorCenters = new Map(sectors.map((sector, i) => {
    const angle = (i / sectors.length) * Math.PI * 2;
    return [sector, {
      x: center.x + Math.cos(angle) * clusterRadius,
      y: center.y + Math.sin(angle) * clusterRadius
    }];
  }));

  const sectorCounts = {};
  nodes.forEach(d => {
    const idx = sectorCounts[d.sector] || 0;
    sectorCounts[d.sector] = idx + 1;
    const col = idx % 5;
    const row = Math.floor(idx / 5);
    const c = sectorCenters.get(d.sector);
    d.x = c.x + (col - 2) * 12;
    d.y = c.y + (row - 2) * 12;
  });

  const simulation = d3.forceSimulation(nodes)
    .force('x', d3.forceX(d => sectorCenters.get(d.sector).x).strength(0.12))
    .force('y', d3.forceY(d => sectorCenters.get(d.sector).y).strength(0.12))
    .force('collide', d3.forceCollide(d => d.radius + 1).iterations(2))
    .force('center', d3.forceCenter(center.x, center.y))
    .stop();

  simulation.tick(320);

  const node = nodeLayer.selectAll('g')
    .data(nodes, d => d.ticker)
    .enter()
    .append('g')
    .attr('class', d => `node ${d.isEtf ? 'etf' : 'stock'}`)
    .attr('transform', d => `translate(${d.x},${d.y})`)
    .on('click', (event, d) => {
      setSelected(d.ticker, node, row);
    })
    .on('mouseover', async (event, d) => {
      if (d.isEtf) return;
      activeTooltipTicker = d.ticker;
      tooltip.html(tooltipHtml(d));
      positionTooltip(event);
      tooltip.classed('visible', true);

      const history = await loadPriceHistory(d.ticker);
      if (!history || activeTooltipTicker !== d.ticker) return;
      const cleaned = history.filter(h => h.date && !Number.isNaN(h.close));
      const recent = cleaned.slice(-60);
      renderSparkline(tooltip.select('svg'), recent);
    })
    .on('mousemove', (event, d) => {
      if (d.isEtf) return;
      positionTooltip(event);
    })
    .on('mouseout', (event, d) => {
      if (d.isEtf) return;
      hideTooltip();
    });

  node.append('circle')
    .attr('r', d => d.radius)
    .attr('fill', d => color(d.sector))
    .attr('opacity', d => d.isEtf ? 0.75 : 0.9);

  node.append('text')
    .attr('class', 'node-label')
    .attr('text-anchor', 'middle')
    .attr('dy', '0.35em')
    .text(d => d.ticker);

  buildLegend(sectors, color);

  const tableData = nodes.slice().sort((a, b) => d3.ascending(a.ticker, b.ticker));
  const table = d3.select('#stock-table');
  const columns = ['Ticker symbol', 'Full company name', 'Sector', 'Market cap'];

  table.append('thead')
    .append('tr')
    .selectAll('th')
    .data(columns)
    .enter()
    .append('th')
    .text(d => d);

  const tbody = table.append('tbody');

  const row = tbody.selectAll('tr')
    .data(tableData, d => d.ticker)
    .enter()
    .append('tr')
    .attr('class', d => d.isEtf ? 'etf-row' : null)
    .on('click', (event, d) => {
      setSelected(d.ticker, node, row);
    });

  row.append('td').attr('class', 'col-ticker').text(d => d.ticker);
  row.append('td').attr('class', 'col-name').text(d => d.fullName);
  row.append('td').attr('class', 'col-sector').text(d => d.sector);
  row.append('td').attr('class', 'col-marketcap').text(d => formatMarketCap(d.marketCap));
}).catch(error => {
  console.error('Error loading data:', error);
});
JS"}

