}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  font-family: "Gill Sans", "Trebuchet MS", "Calibri", sans-serif;
  color: var(--text-main);
  background: radial-gradient(circle at top, var(--bg-start), var(--bg-end));
}

.page {
  max-width: 1280px;
  margin: 0 auto;
  padding: 28px 24px 32px;
}

header {
  margin-bottom: 18px;
}

h1 {
  margin: 0 0 6px;
  font-size: 28px;
  letter-spacing: 0.3px;
}

header p {
  margin: 0;
