}

.layout {
  display: flex;
  gap: 22px;
  align-items: stretch;
}

.panel {
  background: var(--panel-bg);
  border: 1px solid var(--panel-border);
  border-radius: 18px;
  padding: 16px 16px 18px;
  box-shadow: 0 12px 32px rgba(31, 41, 51, 0.12);
  backdrop-filter: blur(2px);
}

.chart-panel {
  flex: 1 1 58%;
}

.table-panel {
  flex: 1 1 42%;
  display: flex;
  flex-direction: column;
}

.panel h2 {
  margin: 0 0 10px;
  font-size: 18px;
}

#bubble-chart {
  width: 100%;
}

.nodes .node {
  cursor: pointer;
}

.nodes circle {
  stroke: rgba(31, 41, 51, 0.35);
  stroke-width: 1;
}

.nodes .node.selected circle {
  stroke: #0c4a6e;
  stroke-width: 3;
}

.node-label {
  font-size: 11px;
  fill: #1f2933;
  pointer-events: none;
  font-weight: 600;
}

.legend {
  margin-top: 12px;
  display: flex;
  flex-wrap: wrap;
  gap: 10px 14px;
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  color: var(--text-muted);
}

.legend-swatch {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  border: 1px solid rgba(31, 41, 51, 0.3);
}

.table-wrap {
  flex: 1 1 auto;
  overflow: auto;
  border-radius: 12px;
  border: 1px solid #e1e7ef;
  background: white;
}

#stock-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}

#stock-table thead th {
  position: sticky;
  top: 0;
  background: #f0f4f8;
  text-align: left;
  padding: 10px 8px;
  font-size: 12px;
  color: var(--text-muted);
  letter-spacing: 0.2px;
  z-index: 1;
  border-bottom: 1px solid #e1e7ef;
}

#stock-table tbody tr {
  cursor: pointer;
}

#stock-table tbody tr:nth-child(even) {
  background: #f9fbfd;
}

#stock-table tbody td {
  padding: 8px;
  border-bottom: 1px solid #eef2f7;
  vertical-align: top;
}

#stock-table tbody tr.selected {
  background: var(--highlight);
}

#stock-table tbody tr.selected td {
  font-weight: 600;
}

.col-ticker {
  font-weight: 700;
  color: var(--accent);
}

.col-marketcap {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.tooltip {
  position: absolute;
  padding: 12px 14px;
  background: rgba(16, 24, 40, 0.92);
  color: #f8fafc;
  border-radius: 10px;
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.2s ease;
  z-index: 20;
  width: 220px;
  box-shadow: 0 12px 32px rgba(15, 23, 42, 0.35);
}

.tooltip.visible {
  opacity: 1;
}

.tip-title {
  font-size: 15px;
  font-weight: 700;
}

.tip-subtitle {
  font-size: 12px;
  margin-top: 2px;
  color: #cbd5e1;
}

.tip-sector {
  font-size: 12px;
  margin-top: 6px;
  color: #e2e8f0;
}

.tip-sparkline {
  margin-top: 8px;
}

.tip-sparkline-label {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: #94a3b8;
  margin-bottom: 4px;
}

.sparkline {
  fill: none;
  stroke: #fbbf24;
  stroke-width: 2;
}

.sparkline-dot {
  fill: #fde68a;
}

@media (max-width: 980px) {
  .layout {
    flex-direction: column;
  }

  .chart-panel,
  .table-panel {
    flex: 1 1 100%;
  }

  #stock-table {
    font-size: 12px;
  }
}
CSS"}

